/* P6 · 策略推演中心（US-01 / R-OPT-01-02）· 前端模块。
 *
 * 由原「空间惩罚项配置」（P6）与「假设推演」（P10）合并而成，一条页面主线：
 *   推演输入 = 拟议规则（可选）+ 市场情景（可选，仅 admin），二者必填其一 → 一次运行。
 *   互斥分支（原 T6 模式 chip 已删）：勾选「不挂规则」→ 仅情景的组合压力测试；
 *   未勾选 → 规则必填（可叠加情景压力背景）。
 *   两腿真正打通：定量腿在情景冲击后的 LTV 上重算命中（ shock 对比块），
 *   叙事腿围绕拟议规则评估「该情景下够不够」——情景是规则的压力背景，
 *   不是平行无关的第二输入。保存落库的始终是无冲击的原规则。
 *   中间以 R-OPT-01 红线分隔——定量结论可以落库生效，
 *   定性叙事只能用于探索，这条边界必须一直摆在用户眼前。
 *
 * 「运行推演」不是装饰——策略配置一旦落库就会进审批链路，风控经理必须先看到
 * 「会波及多少存量、多少笔从通过翻成拒贷」才敢按保存，这是 PRD §5.3 策略沙盒的雏形。
 *
 * 整个文件包在 IIFE 里：插件 js 是普通 <script> 注入（非 ES module），
 * 顶层 const 会挂到全局，与 app.js 的 `const state` 直接重名报错。
 */
